localparam int H_active = 640;
localparam int V_active = 480;

localparam int paddlewidth = 15;
localparam int paddleheight = 60;

localparam int L_position = 20;
localparam int R_position = 20;

always_ff @ (posedge clk_1ms)
begin
    if(!SW[0])
    begin
        x_paddle1 <= L_position + (paddlewidth/2);
        y_paddle1 <= V_active/2;
    end
    else if (!KEY[0] && y_paddle1-(paddleheight/2) > 0)
        y_paddle1 <= y_paddle1-1;
    else if (!KEY[1] && y_paddle1+(paddleheight/2) < V_active)
        y_paddle1 <= y_paddle1+1;
    else 
        y_paddle1 <= y_paddle1;
end

assign paddle1_on = (x >= x_paddle1-(paddlewidth/2) && x <= x_paddle1+(paddlewidth/2) && y >= y_paddle1-(paddleheight/2) && y < y_paddle1+(paddleheight/2))?1'b1:1'b0;

assign rgb_paddle1 = 12'b000011110000; 

//Second padlle
