begin
    if(!SW[0])
    begin    
        x_paddle2 <= H_active-(R_position + (paddlewidth/2));
        y_paddle2 <= V_active/2;
    end
    else if (data_y[12] && y_paddle2-(paddleheight/2) > 0)
        y_paddle2 <= y_paddle2-1;
    else if (!data_y[12] && y_paddle2+(paddleheight/2) < V_active )
        y_paddle2 <= y_paddle2+1;
    else 
        y_paddle2 <= y_paddle2;
end


assign paddle2_on = (x >= x_paddle2-(paddlewidth/2) && x <= x_paddle2+(paddlewidth/2) && y >= y_paddle2-(paddleheight/2) && y < y_paddle2+(paddleheight/2))?1'b1:1'b0;
